export interface JournalDraft {
  body: string;
  writerKey: string;
  replyToKey?: string;
  assetKey?: string;
}

export interface JournalRecord extends JournalDraft {
  logicalStep: number;
  reads: number;
  replies: number;
  stars: number;
  shares: number;
}

function validKey(value: string): boolean {
  return /^[0-9A-F]{16}$/.test(value);
}

export function buildJournalRecord(
  draft: JournalDraft,
  logicalStep: number
): JournalRecord {
  if (draft.body.trim().length === 0) throw new Error("body is empty");
  if (draft.body.length >= 240) throw new Error("body is too long");
  if (!validKey(draft.writerKey)) throw new Error("invalid writer key");
  if (draft.replyToKey !== undefined && !validKey(draft.replyToKey)) {
    throw new Error("invalid reply key");
  }
  if (draft.assetKey !== undefined && !validKey(draft.assetKey)) {
    throw new Error("invalid asset key");
  }
  if (!Number.isSafeInteger(logicalStep) || logicalStep < 0) {
    throw new Error("invalid logical step");
  }
  return {
    ...draft,
    logicalStep,
    reads: 0,
    replies: 0,
    stars: 0,
    shares: 0
  };
}
```

