import { JournalDraft, buildJournalRecord } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(fn: () => unknown, message: string): void {
  let didThrow = false;
  try { fn(); } catch (error) { didThrow = error instanceof Error; }
  assert(didThrow, message);
}

const draft: JournalDraft = {
  body: " Original body ",
  writerKey: "0123456789ABCDEF",
  replyToKey: "FFFFFFFFFFFFFFFF",
  assetKey: "ABCDEF0123456789"
};
const record = buildJournalRecord(draft, 0);
equal(record.body, " Original body ", "body is preserved exactly");
equal(record.writerKey, "0123456789ABCDEF", "writer key is preserved");
equal(record.replyToKey, "FFFFFFFFFFFFFFFF", "reply key is preserved");
equal(record.assetKey, "ABCDEF0123456789", "asset key is preserved");
equal(record.logicalStep, 0, "zero logical step is valid");
equal(record.reads, 0, "reads starts at zero");
equal(record.replies, 0, "replies starts at zero");
equal(record.stars, 0, "stars starts at zero");
equal(record.shares, 0, "shares starts at zero");
assert(record !== (draft as unknown), "result is a new object");
draft.body = "Later mutation";
draft.writerKey = "FFFFFFFFFFFFFFFF";
equal(record.body, " Original body ", "result does not alias the draft");
equal(record.writerKey, "0123456789ABCDEF", "later draft changes do not affect result");

const exactly240 = "x".repeat(240);
equal(buildJournalRecord({ body: exactly240, writerKey: "0000000000000000" }, Number.MAX_SAFE_INTEGER).body.length, 240, "240 UTF-16 code units are accepted");
equal(buildJournalRecord({ body: "😀".repeat(120), writerKey: "AAAAAAAAAAAAAAAA" }, 1).body.length, 240, "UTF-16 code-unit boundary handles surrogate pairs");
throws(() => buildJournalRecord({ body: "x".repeat(241), writerKey: "0000000000000000" }, 0), "241 code units are rejected");
throws(() => buildJournalRecord({ body: "😀".repeat(120) + "x", writerKey: "0000000000000000" }, 0), "surrogate-pair body over boundary is rejected");
throws(() => buildJournalRecord({ body: " \t\n ", writerKey: "0000000000000000" }, 0), "whitespace-only body is rejected");

for (const writerKey of ["", "0123456789ABCDE", "0123456789ABCDEFF", "0123456789abcDEF", "G123456789ABCDEF", " 123456789ABCDEF"]) {
  throws(() => buildJournalRecord({ body: "body", writerKey }, 0), `invalid writer key is rejected: ${writerKey}`);
}
throws(() => buildJournalRecord({ body: "body", writerKey: "0000000000000000", replyToKey: "bad" }, 0), "invalid defined reply key is rejected");
throws(() => buildJournalRecord({ body: "body", writerKey: "0000000000000000", assetKey: "0123456789abcdef" }, 0), "invalid defined asset key is rejected");
buildJournalRecord({ body: "body", writerKey: "0000000000000000", replyToKey: undefined, assetKey: undefined }, 0);

for (const logicalStep of [-1, 1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1]) {
  throws(() => buildJournalRecord({ body: "body", writerKey: "0000000000000000" }, logicalStep), `invalid logical step is rejected: ${String(logicalStep)}`);
}

